/* Airlie 30 "Wright" – 3D walkthrough.
 * Geometry comes from model.js (generated by tools/build_model.py from the plan PDF).
 * Model units are millimetres: X west->east, Z rear->street, Y up.  Scene units are metres.
 */
(function () {
  'use strict';
  const M = window.HOUSE_MODEL;
  const S = 0.001;
  const EYE = 1.62, RADIUS = 0.2, STEP = 0.5, CUT = 1.35, GRASS_Y = -0.25;
  const LV = M.levels;
  const $ = (id) => document.getElementById(id);

  // ------------------------------------------------------------------ renderer / scene
  const canvas = $('view');
  const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0xcfe2ef);
  const camera = new THREE.PerspectiveCamera(72, 1, 0.05, 200);
  camera.rotation.order = 'YXZ';
  scene.add(camera);

  scene.add(new THREE.AmbientLight(0xffffff, 0.5));
  scene.add(new THREE.HemisphereLight(0xffffff, 0xb9ab95, 0.28));
  const sun = new THREE.DirectionalLight(0xfff4e0, 0.42);
  sun.position.set(-8, 20, -6);
  scene.add(sun);
  const lamp = new THREE.PointLight(0xfff1dc, 0.22, 10, 1);   // soft light that travels with the viewer
  camera.add(lamp);

  const aniso = renderer.capabilities.getMaxAnisotropy();

  // ------------------------------------------------------------------ procedural textures
  function tex(size, draw, tileMetres) {
    const c = document.createElement('canvas'); c.width = c.height = size;
    draw(c.getContext('2d'), size);
    const t = new THREE.CanvasTexture(c);
    t.wrapS = t.wrapT = THREE.RepeatWrapping; t.anisotropy = aniso;
    t.userData = { tile: tileMetres };
    return t;
  }
  function noise(g, n, size, alpha, light) {
    for (let i = 0; i < n; i++) {
      g.fillStyle = (light ? 'rgba(255,255,255,' : 'rgba(0,0,0,') + (Math.random() * alpha) + ')';
      g.fillRect(Math.random() * size, Math.random() * size, 1 + Math.random() * 2, 1 + Math.random() * 2);
    }
  }
  const TEX = {
    timber: tex(512, (g, s) => {
      const rows = 8, h = s / rows;
      for (let r = 0; r < rows; r++) {
        let x = -((r * 97) % 200);
        while (x < s) {
          const w = 180 + ((r * 53 + x * 7) % 140);
          const t = 0.95 + 0.1 * (((x * 13 + r * 31) % 100) / 100);
          g.fillStyle = `rgb(${Math.round(176 * t)},${Math.round(132 * t)},${Math.round(92 * t)})`;
          g.fillRect(x, r * h, w, h);
          g.fillStyle = 'rgba(60,35,15,0.35)'; g.fillRect(x, r * h, 1.5, h);
          x += w;
        }
        g.fillStyle = 'rgba(60,35,15,0.3)'; g.fillRect(0, r * h, s, 1.5);
      }
      noise(g, 2500, s, 0.07, false);
    }, 1.2),
    carpet: tex(256, (g, s) => {
      g.fillStyle = '#b4ada2'; g.fillRect(0, 0, s, s);
      noise(g, 5000, s, 0.12, false); noise(g, 4000, s, 0.12, true);
    }, 0.9),
    tile: tex(512, (g, s) => {
      g.fillStyle = '#c3cccc'; g.fillRect(0, 0, s, s);
      g.strokeStyle = '#9aa5a6'; g.lineWidth = 3;
      for (let i = 0; i <= 2; i++) { g.beginPath(); g.moveTo(i * s / 2, 0); g.lineTo(i * s / 2, s); g.stroke(); g.beginPath(); g.moveTo(0, i * s / 2); g.lineTo(s, i * s / 2); g.stroke(); }
      noise(g, 900, s, 0.05, false);
    }, 1.2),
    concrete: tex(256, (g, s) => {
      g.fillStyle = '#a4a7a9'; g.fillRect(0, 0, s, s);
      noise(g, 4000, s, 0.1, false); noise(g, 3000, s, 0.1, true);
    }, 3),
  };
  const FLOOR_MAT = {};
  for (const k in TEX) FLOOR_MAT[k] = new THREE.MeshLambertMaterial({ map: TEX[k] });

  const MAT = {
    wall: new THREE.MeshLambertMaterial({ color: 0xe9e5dd }),
    frame: new THREE.MeshLambertMaterial({ color: 0x2c3035 }),
    stair: new THREE.MeshLambertMaterial({ color: 0xb98b5a }),
    guard: new THREE.MeshLambertMaterial({ color: 0xe9e6e0 }),
    ceiling: new THREE.MeshLambertMaterial({ color: 0xf1efea }),
    glass: new THREE.MeshPhongMaterial({ color: 0x9cc7dc, transparent: true, opacity: 0.3, shininess: 90, specular: 0xffffff, depthWrite: false, side: THREE.DoubleSide }),
    obscure: new THREE.MeshPhongMaterial({ color: 0xe9f1f4, transparent: true, opacity: 0.82, shininess: 20, depthWrite: false, side: THREE.DoubleSide }),
    grass: new THREE.MeshLambertMaterial({ color: 0x6f8f5e }),
  };
  const colMats = {};
  const colMat = (hex) => colMats[hex] || (colMats[hex] = new THREE.MeshLambertMaterial({ color: new THREE.Color(hex) }));

  // ------------------------------------------------------------------ scene graph
  const G = { G: new THREE.Group(), F: new THREE.Group() };
  const parts = {};   // parts[level] = {walls, fur, glass, floors, ceil, labels}
  for (const l of ['G', 'F']) {
    parts[l] = {};
    for (const k of ['walls', 'fur', 'glass', 'floors', 'ceil', 'labels']) { parts[l][k] = new THREE.Group(); G[l].add(parts[l][k]); }
    scene.add(G[l]);
  }
  const ground = new THREE.Mesh(new THREE.PlaneGeometry(160, 160), MAT.grass);
  ground.rotation.x = -Math.PI / 2; ground.position.set(5.6, GRASS_Y - 0.01, 12.2);
  scene.add(ground);

  const cutMeshes = [];   // every box mesh, for the cutaway view
  const COLL = [];        // collision boxes (metres)
  const SURF = [];        // walkable surfaces (metres)

  function addBox(b, mat, parent, collide, isTread, level) {
    const w = (b[3] - b[0]) * S, h = (b[4] - b[1]) * S, d = (b[5] - b[2]) * S;
    if (mat) {
      const g = new THREE.BoxGeometry(w, h, d); g.translate(0, h / 2, 0);
      const m = new THREE.Mesh(g, mat);
      m.position.set((b[0] + b[3]) / 2 * S, b[1] * S, (b[2] + b[5]) / 2 * S);
      m.userData = { y0: b[1] * S, y1: b[4] * S, h };
      parent.add(m); cutMeshes.push(m);
    }
    if (collide) {
      // ground-floor walls only block up to the ground ceiling: the slab above belongs to the first floor
      const top = level === 'G' && !isTread ? Math.min(b[4], LV.G.ceil) : b[4];
      COLL.push({ x0: b[0] * S, x1: b[3] * S, z0: b[2] * S, z1: b[5] * S, y0: b[1] * S, y1: top * S, tread: !!isTread });
    }
  }

  for (const b of M.boxes) {
    const P = parts[b.l];
    const solid = b.c === 'wall' || b.c === 'solid' || b.c === 'tread';
    if (b.m === 'wall') addBox(b.b, MAT.wall, P.walls, solid, false, b.l);
    else if (b.m === 'frame') addBox(b.b, b.col ? colMat(b.col) : MAT.frame, P.walls, solid, false, b.l);
    else if (b.m === 'door') addBox(b.b, colMat(b.col || '#ece9e3'), P.walls, solid, false, b.l);
    else if (b.m === 'stair') addBox(b.b, MAT.stair, P.walls, solid, true, b.l);
    else if (b.m === 'guard') addBox(b.b, MAT.guard, P.walls, solid, false, b.l);
    else if (b.m === 'fur') addBox(b.b, colMat(b.col), P.fur, solid, false, b.l);
    else if (b.m === 'none') addBox(b.b, null, null, solid, false, b.l);
  }
  for (const g of M.glass) addBox(g.b, g.obscure ? MAT.obscure : MAT.glass, parts[g.l].glass, false);

  // floors + ceilings: merge rectangles per material
  function quads(rects, y, tile, up) {
    const n = rects.length, pos = new Float32Array(n * 12), uv = new Float32Array(n * 8), nor = new Float32Array(n * 12), idx = new Uint32Array(n * 6);
    rects.forEach((r, i) => {
      const x0 = r[0] * S, z0 = r[1] * S, x1 = r[2] * S, z1 = r[3] * S;
      pos.set([x0, y, z0, x1, y, z0, x1, y, z1, x0, y, z1], i * 12);
      uv.set([x0 / tile, z0 / tile, x1 / tile, z0 / tile, x1 / tile, z1 / tile, x0 / tile, z1 / tile], i * 8);
      for (let k = 0; k < 4; k++) { nor[i * 12 + k * 3 + 1] = up ? 1 : -1; }
      const o = i * 4;
      if (up) idx.set([o, o + 2, o + 1, o, o + 3, o + 2], i * 6); else idx.set([o, o + 1, o + 2, o, o + 2, o + 3], i * 6);
    });
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.BufferAttribute(pos, 3)); g.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
    g.setAttribute('normal', new THREE.BufferAttribute(nor, 3)); g.setIndex(new THREE.BufferAttribute(idx, 1));
    return g;
  }
  const floorGroups = {};
  for (const f of M.floors) {
    const key = f.l + '|' + f.f + '|' + f.y;
    (floorGroups[key] = floorGroups[key] || { l: f.l, f: f.f, y: f.y, r: [] }).r.push(f.r);
    SURF.push({ x0: f.r[0] * S, z0: f.r[1] * S, x1: f.r[2] * S, z1: f.r[3] * S, y: f.y * S });
  }
  for (const k in floorGroups) {
    const fg = floorGroups[k];
    const mesh = new THREE.Mesh(quads(fg.r, fg.y * S, TEX[fg.f].userData.tile, true), FLOOR_MAT[fg.f]);
    parts[fg.l].floors.add(mesh);
  }
  const ceilGroups = {};
  for (const c of M.ceilings) (ceilGroups[c.l + '|' + c.y] = ceilGroups[c.l + '|' + c.y] || { l: c.l, y: c.y, r: [] }).r.push(c.r);
  for (const k in ceilGroups) {
    const cg = ceilGroups[k];
    parts[cg.l].ceil.add(new THREE.Mesh(quads(cg.r, cg.y * S, 1, false), MAT.ceiling));
  }
  for (const w of M.walk) SURF.push({ x0: w.r[0] * S, z0: w.r[1] * S, x1: w.r[2] * S, z1: w.r[3] * S, y: w.y * S });

  // room labels (flat text on the floor, readable from above)
  function labelSprite(text, sub) {
    const c = document.createElement('canvas'); c.width = 512; c.height = 160;
    const g = c.getContext('2d');
    g.textAlign = 'center'; g.textBaseline = 'middle';
    g.font = '600 54px system-ui, Segoe UI, Arial'; g.lineWidth = 9; g.strokeStyle = 'rgba(255,255,255,0.95)'; g.fillStyle = '#1d2630';
    g.strokeText(text, 256, sub ? 56 : 80); g.fillText(text, 256, sub ? 56 : 80);
    if (sub) { g.font = '500 38px system-ui, Segoe UI, Arial'; g.strokeText(sub, 256, 118); g.fillStyle = '#4b5663'; g.fillText(sub, 256, 118); }
    const t = new THREE.CanvasTexture(c); t.anisotropy = aniso;
    const m = new THREE.Mesh(new THREE.PlaneGeometry(3.4, 1.0625), new THREE.MeshBasicMaterial({ map: t, transparent: true, depthWrite: false, depthTest: false }));
    m.rotation.x = -Math.PI / 2; m.renderOrder = 20;
    return m;
  }
  for (const l of M.labels) {
    const m = labelSprite(l.t, l.s);
    m.position.set(l.x * S, LV[l.l].floor * S + 1.05, l.z * S);
    parts[l.l].labels.add(m);
  }

  // ------------------------------------------------------------------ player & collision
  const P = { x: 0, z: 0, feet: 0, eye: EYE, yaw: 0, pitch: 0 };
  // treads can be stepped onto (up to STEP high); everything else only needs 0.3 m of clearance
  const vOverlap = (c, feet) => c.y1 > feet + (c.tread ? STEP : 0.3) && c.y0 < feet + 1.6;
  function blocked(x, z, feet) {
    for (let i = 0; i < COLL.length; i++) {
      const c = COLL[i];
      if (!vOverlap(c, feet)) continue;
      const cx = x < c.x0 ? c.x0 : x > c.x1 ? c.x1 : x, cz = z < c.z0 ? c.z0 : z > c.z1 ? c.z1 : z;
      const dx = x - cx, dz = z - cz;
      if (dx * dx + dz * dz < RADIUS * RADIUS) return true;
    }
    return false;
  }
  function surfaceAt(x, z, feet) {
    let best = -Infinity;
    for (let i = 0; i < SURF.length; i++) {
      const s = SURF[i];
      if (s.y <= feet + STEP && s.y > best && x >= s.x0 && x <= s.x1 && z >= s.z0 && z <= s.z1) best = s.y;
    }
    return best === -Infinity ? GRASS_Y : best;
  }
  const BOUNDS = { x0: -2.0, x1: 13.5, z0: -1.0, z1: 24.5 };
  function tryMove(dx, dz) {
    let nx = P.x + dx, nz = P.z;
    nx = Math.min(BOUNDS.x1, Math.max(BOUNDS.x0, nx));
    if (!blocked(nx, nz, P.feet)) P.x = nx;
    nz = Math.min(BOUNDS.z1, Math.max(BOUNDS.z0, P.z + dz));
    if (!blocked(P.x, nz, P.feet)) P.z = nz;
    P.feet = surfaceAt(P.x, P.z, P.feet);
  }
  function findFree(x, z, feet) {
    if (!blocked(x, z, feet)) return [x, z];
    for (let r = 0.2; r < 3; r += 0.2) {
      for (let a = 0; a < 6.28; a += 0.4) {
        const nx = x + Math.cos(a) * r, nz = z + Math.sin(a) * r;
        if (!blocked(nx, nz, feet)) return [nx, nz];
      }
    }
    return [x, z];
  }
  function levelOf(feet) { return feet > 1.6 ? 'F' : 'G'; }

  // ------------------------------------------------------------------ view modes
  const state = { mode: 'walk', level: 'G', ceil: true, labels: false, fur: true, cut: true, view: 'B' };
  const orbit = { a: 0.0, phi: 0.95, r: 38, t: new THREE.Vector3(5.6, 1.2, 12.2) };

  function applyVisibility() {
    const walk = state.mode === 'walk';
    const showG = walk || state.view !== 'F';
    const showF = walk || state.view !== 'G';
    G.G.visible = showG; G.F.visible = showF;
    for (const l of ['G', 'F']) {
      parts[l].ceil.visible = state.ceil && (walk || false);
      parts[l].fur.visible = state.fur;
      // 'Both' view: only first-floor labels, otherwise ground labels would show through the slab
      parts[l].labels.visible = state.labels && (walk || state.view !== 'B' || l === 'F');
    }
    const cut = !walk && state.cut;
    for (const m of cutMeshes) {
      const u = m.userData;
      const lvlFloor = (m.position.y >= LV.F.floor * S - 0.01) ? LV.F.floor * S : 0;
      const cutY = lvlFloor + CUT;
      if (!cut) { m.visible = true; m.scale.y = 1; continue; }
      if (u.y0 >= cutY - 1e-6) { m.visible = false; continue; }
      m.visible = true;
      m.scale.y = Math.max(0.001, (Math.min(u.y1, cutY) - u.y0) / (u.y1 - u.y0));
    }
    // ceilings only make sense when walking; in dollhouse view the user may still opt in
    if (!walk && state.ceil) for (const l of ['G', 'F']) parts[l].ceil.visible = !cut;
    // glass above the cut would float: handled by cutMeshes (glass meshes are included)
  }

  function setMode(mode) {
    state.mode = mode;
    camera.fov = mode === 'walk' ? 72 : 38; camera.updateProjectionMatrix();
    if (mode === 'orbit') orbit.r = Math.min(80, 38 * Math.max(1, 0.8 / camera.aspect));   // portrait screens: stand further back
    if (mode === 'walk') { state.ceil = true; state.labels = false; }
    else { state.ceil = false; state.labels = true; }
    syncUI(); applyVisibility();
  }

  function teleport(x, z, level, yaw, pitch) {
    const feet = LV[level].floor * S;
    const f = findFree(x * S, z * S, feet);
    P.x = f[0]; P.z = f[1]; P.feet = surfaceAt(P.x, P.z, feet + 0.01);
    P.eye = P.feet + EYE;
    if (yaw !== undefined) P.yaw = yaw;
    if (pitch !== undefined) P.pitch = pitch;
  }
  function goLevel(level) {
    const sp = M.spawns[level];
    teleport(sp.x, sp.z, level, sp.yaw, 0);
  }

  // ------------------------------------------------------------------ input
  const keys = {};
  let lastMoveInput = 0;
  window.addEventListener('keydown', (e) => {
    if (e.target && /INPUT|SELECT|TEXTAREA/.test(e.target.tagName)) return;
    keys[e.code] = true;
    if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space'].includes(e.code)) e.preventDefault();
    if (e.code === 'Tab') { e.preventDefault(); setMode(state.mode === 'walk' ? 'orbit' : 'walk'); }
    if (e.code === 'KeyC') { $('tCeil').click(); }
    if (e.code === 'KeyM') { $('mini').classList.toggle('hide'); }
  });
  window.addEventListener('keyup', (e) => { keys[e.code] = false; });
  window.addEventListener('blur', () => { for (const k in keys) keys[k] = false; });

  const joy = { id: null, x: 0, y: 0, ox: 0, oy: 0 };
  const look = { id: null, x: 0, y: 0, moved: 0 };
  const pointers = new Map();
  let pinch = 0;

  function lockSupported() { return 'requestPointerLock' in canvas && matchMedia('(pointer:fine)').matches; }
  canvas.addEventListener('pointerdown', (e) => {
    canvas.setPointerCapture(e.pointerId);
    pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
    if (state.mode === 'walk') {
      if (e.pointerType === 'touch' && e.clientX < innerWidth * 0.42 && e.clientY > innerHeight * 0.45 && joy.id === null) {
        joy.id = e.pointerId; joy.ox = e.clientX; joy.oy = e.clientY; joy.x = joy.y = 0;
        const st = $('stick'); st.style.display = 'block'; st.style.left = (e.clientX - 55) + 'px'; st.style.top = (e.clientY - 55) + 'px';
        $('knob').style.transform = 'translate(0px,0px)';
      } else if (look.id === null) { look.id = e.pointerId; look.x = e.clientX; look.y = e.clientY; look.moved = 0; }
    } else {
      look.id = e.pointerId; look.x = e.clientX; look.y = e.clientY; look.moved = 0;
      if (pointers.size === 2) { const [a, b] = [...pointers.values()]; pinch = Math.hypot(a.x - b.x, a.y - b.y); }
    }
  });
  canvas.addEventListener('pointermove', (e) => {
    const p = pointers.get(e.pointerId); if (p) { p.x = e.clientX; p.y = e.clientY; }
    if (state.mode === 'walk') {
      if (e.pointerId === joy.id) {
        let dx = e.clientX - joy.ox, dy = e.clientY - joy.oy; const m = Math.hypot(dx, dy), max = 50;
        if (m > max) { dx = dx / m * max; dy = dy / m * max; }
        joy.x = dx / max; joy.y = dy / max; $('knob').style.transform = `translate(${dx}px,${dy}px)`;
      } else if (document.pointerLockElement === canvas) {
        P.yaw -= e.movementX * 0.0022; P.pitch = Math.max(-1.45, Math.min(1.45, P.pitch - e.movementY * 0.0022));
      } else if (e.pointerId === look.id && (e.buttons || e.pointerType === 'touch')) {
        const dx = e.clientX - look.x, dy = e.clientY - look.y; look.x = e.clientX; look.y = e.clientY; look.moved += Math.abs(dx) + Math.abs(dy);
        const k = e.pointerType === 'touch' ? 0.0042 : 0.0030;
        P.yaw -= dx * k; P.pitch = Math.max(-1.45, Math.min(1.45, P.pitch - dy * k));
      }
    } else if (e.pointerId === look.id || pointers.size === 2) {
      if (pointers.size === 2) {
        const [a, b] = [...pointers.values()]; const d = Math.hypot(a.x - b.x, a.y - b.y);
        if (pinch) orbit.r = Math.min(80, Math.max(4, orbit.r * pinch / d)); pinch = d;
        const dx = (e.clientX - look.x), dy = (e.clientY - look.y); look.x = e.clientX; look.y = e.clientY; panOrbit(dx * 0.5, dy * 0.5);
      } else if (e.buttons || e.pointerType === 'touch') {
        const dx = e.clientX - look.x, dy = e.clientY - look.y; look.x = e.clientX; look.y = e.clientY; look.moved += Math.abs(dx) + Math.abs(dy);
        if (e.buttons & 2 || e.shiftKey || e.buttons & 4) panOrbit(dx, dy);
        else { orbit.a -= dx * 0.0055; orbit.phi = Math.min(1.5, Math.max(0.06, orbit.phi - dy * 0.005)); }
      }
    }
  });
  function endPointer(e) {
    pointers.delete(e.pointerId); pinch = 0;
    if (e.pointerId === joy.id) { joy.id = null; joy.x = joy.y = 0; $('stick').style.display = 'none'; }
    if (e.pointerId === look.id) {
      if (state.mode === 'walk' && look.moved < 5 && e.pointerType === 'mouse' && lockSupported() && document.pointerLockElement !== canvas) {
        try { const r = canvas.requestPointerLock(); if (r && r.catch) r.catch(() => {}); } catch (_) {}
      }
      look.id = null;
    }
  }
  canvas.addEventListener('pointerup', endPointer); canvas.addEventListener('pointercancel', endPointer);
  canvas.addEventListener('contextmenu', (e) => e.preventDefault());
  canvas.addEventListener('wheel', (e) => {
    e.preventDefault();
    if (state.mode === 'orbit') orbit.r = Math.min(80, Math.max(4, orbit.r * Math.exp(e.deltaY * 0.0012)));
    else { camera.fov = Math.min(95, Math.max(45, camera.fov + e.deltaY * 0.03)); camera.updateProjectionMatrix(); }
  }, { passive: false });
  function panOrbit(dx, dy) {
    // drag the scene: target moves opposite to screen-right, and along "forward" for a downward drag
    const k = orbit.r * 0.0016, sa = Math.sin(orbit.a), ca = Math.cos(orbit.a);
    orbit.t.x += (-ca * dx - sa * dy) * k;
    orbit.t.z += (sa * dx - ca * dy) * k;
    orbit.t.x = Math.min(14, Math.max(-3, orbit.t.x)); orbit.t.z = Math.min(26, Math.max(-1, orbit.t.z));
  }

  // ------------------------------------------------------------------ per-frame update
  const fwd = new THREE.Vector3();
  let last = performance.now();
  function update(dt) {
    if (state.mode === 'walk') {
      let f = 0, s = 0, turn = 0;
      if (keys.KeyW || keys.ArrowUp) f += 1; if (keys.KeyS || keys.ArrowDown) f -= 1;
      if (keys.KeyD) s += 1; if (keys.KeyA) s -= 1;
      if (keys.ArrowLeft || keys.KeyQ) turn += 1; if (keys.ArrowRight || keys.KeyE) turn -= 1;
      if (joy.id !== null) { f += -joy.y; s += joy.x; }
      P.yaw += turn * 1.9 * dt;
      const run = keys.ShiftLeft || keys.ShiftRight ? 2.3 : 1;
      const sp = 1.45 * run;
      const len = Math.hypot(f, s);
      if (len > 0.01) {
        const k = Math.min(1, len) / len;
        const sy = Math.sin(P.yaw), cy = Math.cos(P.yaw);
        // forward = (-sin, -cos), right = (cos, -sin)
        const vx = (-sy * f + cy * s) * k * sp * dt, vz = (-cy * f - sy * s) * k * sp * dt;
        const n = Math.max(1, Math.ceil(Math.hypot(vx, vz) / 0.08));
        for (let i = 0; i < n; i++) tryMove(vx / n, vz / n);
      }
      const target = P.feet + EYE;
      P.eye += (target - P.eye) * Math.min(1, dt * 12);
      camera.position.set(P.x, P.eye, P.z);
      camera.rotation.set(P.pitch, P.yaw, 0);
    } else {
      const sp = Math.sin(orbit.phi), cp = Math.cos(orbit.phi);
      camera.position.set(orbit.t.x + orbit.r * sp * Math.sin(orbit.a), orbit.t.y + orbit.r * cp, orbit.t.z + orbit.r * sp * Math.cos(orbit.a));
      camera.up.set(0, 1, 0); camera.lookAt(orbit.t);
    }
  }

  // ------------------------------------------------------------------ minimap + HUD
  const mini = $('miniCanvas'), mg = mini.getContext('2d');
  const ZMAX = 22800, MW = 190, MH = Math.round(MW * ZMAX / 11600);
  const dpr = Math.min(2, window.devicePixelRatio || 1);
  mini.width = MW * dpr; mini.height = MH * dpr; mini.style.width = MW + 'px'; mini.style.height = MH + 'px';
  const MS = MW / 11600;
  const FIN = { timber: '#e4c9a0', carpet: '#cfd3da', tile: '#b7d3cc', concrete: '#dcdcdc' };
  const miniBase = {};
  function drawBase(l) {
    const c = document.createElement('canvas'); c.width = MW * dpr; c.height = MH * dpr;
    const g = c.getContext('2d'); g.scale(dpr, dpr);
    g.fillStyle = '#f7f7f5'; g.fillRect(0, 0, MW, MH);
    for (const f of M.floors) { if (f.l !== l) continue; g.fillStyle = FIN[f.f]; g.fillRect(f.r[0] * MS, f.r[1] * MS, (f.r[2] - f.r[0]) * MS + 0.6, (f.r[3] - f.r[1]) * MS + 0.6); }
    for (const b of M.boxes) {
      if (b.l !== l) continue;
      const [x0, y0, z0, x1, y1, z1] = b.b;
      if (b.m === 'fur') { g.strokeStyle = 'rgba(90,70,50,0.45)'; g.lineWidth = 0.6; g.strokeRect(x0 * MS, z0 * MS, (x1 - x0) * MS, (z1 - z0) * MS); }
      else if (b.m === 'wall' && y0 === LV[l].floor) { g.fillStyle = '#2b2f34'; g.fillRect(x0 * MS, z0 * MS, Math.max(0.9, (x1 - x0) * MS), Math.max(0.9, (z1 - z0) * MS)); }
      else if (b.m === 'stair' || b.m === 'guard') { g.strokeStyle = '#b0369a'; g.lineWidth = 0.5; g.strokeRect(x0 * MS, z0 * MS, (x1 - x0) * MS, (z1 - z0) * MS); }
    }
    for (const gl of M.glass) { if (gl.l !== l) continue; const [x0, , z0, x1, , z1] = gl.b; g.fillStyle = '#2a9fd6'; g.fillRect(x0 * MS - 0.5, z0 * MS - 0.5, (x1 - x0) * MS + 1, (z1 - z0) * MS + 1); }
    g.font = '600 8px system-ui, Arial'; g.textAlign = 'center'; g.fillStyle = '#26303a';
    for (const t of M.labels) { if (t.l !== l) continue; g.fillText(t.t, t.x * MS, t.z * MS + 3); }
    return c;
  }
  miniBase.G = drawBase('G'); miniBase.F = drawBase('F');
  function drawMini() {
    const l = levelOf(P.feet);
    mg.setTransform(1, 0, 0, 1, 0, 0); mg.clearRect(0, 0, mini.width, mini.height);
    mg.drawImage(miniBase[l], 0, 0);
    mg.setTransform(dpr, 0, 0, dpr, 0, 0);
    let px, pz, yaw;
    if (state.mode === 'walk') { px = P.x * 1000; pz = P.z * 1000; yaw = P.yaw; }
    else { px = orbit.t.x * 1000; pz = orbit.t.z * 1000; yaw = orbit.a + Math.PI; }
    const x = px * MS, y = pz * MS, dx = -Math.sin(yaw), dz = -Math.cos(yaw);
    if (state.mode === 'walk') {
      mg.fillStyle = 'rgba(230,60,40,0.22)'; mg.beginPath(); mg.moveTo(x, y);
      const a0 = Math.atan2(dz, dx) - 0.62, a1 = Math.atan2(dz, dx) + 0.62; mg.arc(x, y, 34, a0, a1); mg.closePath(); mg.fill();
    }
    mg.fillStyle = '#e63c28'; mg.strokeStyle = '#fff'; mg.lineWidth = 1.5;
    mg.beginPath(); mg.arc(x, y, 4.2, 0, 7); mg.fill(); mg.stroke();
    mg.beginPath(); mg.moveTo(x + dx * 9, y + dz * 9); mg.lineTo(x - dz * 3.5, y + dx * 3.5); mg.lineTo(x + dz * 3.5, y - dx * 3.5); mg.closePath(); mg.fill();
    $('miniCap').textContent = LV[l].name;
  }
  mini.addEventListener('pointerdown', (e) => {
    const r = mini.getBoundingClientRect();
    const x = (e.clientX - r.left) / MS, z = (e.clientY - r.top) / MS;
    if (state.mode === 'walk') teleport(x, z, levelOf(P.feet), P.yaw, P.pitch);
    else { orbit.t.x = x * S; orbit.t.z = z * S; }
    e.stopPropagation();
  });

  function roomName() {
    const l = levelOf(P.feet);
    let best = null, bd = 1e12;
    for (const t of M.labels) {
      if (t.l !== l) continue;
      const dx = t.x * S - P.x, dz = t.z * S - P.z, d = dx * dx + dz * dz;
      if (d < bd) { bd = d; best = t; }
    }
    return best && bd < 25 ? best.t : '';
  }
  let hudT = 0;
  function drawHUD(dt) {
    hudT += dt; if (hudT < 0.15) return; hudT = 0;
    if (state.mode === 'walk') {
      const r = roomName();
      $('hud').textContent = (r ? r + ' · ' : '') + LV[levelOf(P.feet)].name;
      syncLevelButtons();
    } else $('hud').textContent = 'Dollhouse view';
  }

  // ------------------------------------------------------------------ UI wiring
  function syncUI() {
    document.querySelectorAll('#modeSeg button').forEach((b) => b.classList.toggle('on', b.dataset.mode === state.mode));
    $('tCeil').checked = state.ceil; $('tLabels').checked = state.labels; $('tFur').checked = state.fur; $('tCut').checked = state.cut;
    $('cutWrap').style.display = state.mode === 'orbit' ? '' : 'none';
    $('bothBtn').style.display = state.mode === 'orbit' ? '' : 'none';
    $('help').dataset.mode = state.mode;
    document.body.dataset.mode = state.mode;
    syncLevelButtons();
  }
  function syncLevelButtons() {
    const cur = state.mode === 'walk' ? levelOf(P.feet) : state.view;
    document.querySelectorAll('#levelSeg button').forEach((b) => b.classList.toggle('on', b.dataset.level === cur));
  }
  document.querySelectorAll('#modeSeg button').forEach((b) => b.addEventListener('click', () => setMode(b.dataset.mode)));
  document.querySelectorAll('#levelSeg button').forEach((b) => b.addEventListener('click', () => {
    const l = b.dataset.level;
    if (state.mode === 'walk') { if (l !== 'B') goLevel(l); }
    else { state.view = l; applyVisibility(); syncLevelButtons(); }
  }));
  $('tCeil').addEventListener('change', (e) => { state.ceil = e.target.checked; applyVisibility(); });
  $('tLabels').addEventListener('change', (e) => { state.labels = e.target.checked; applyVisibility(); });
  $('tFur').addEventListener('change', (e) => { state.fur = e.target.checked; applyVisibility(); });
  $('tCut').addEventListener('change', (e) => { state.cut = e.target.checked; applyVisibility(); });
  $('helpClose').addEventListener('click', () => $('help').classList.add('hide'));
  $('menuBtn').addEventListener('click', () => $('top').classList.toggle('open'));

  const sel = $('rooms');
  const seen = new Set();
  for (const lv of ['G', 'F']) {
    const og = document.createElement('optgroup'); og.label = LV[lv].name;
    for (const t of M.labels) { if (t.l !== lv) continue; const o = document.createElement('option'); o.value = M.labels.indexOf(t); o.textContent = t.t + (t.s ? '  (' + t.s + ' m)' : ''); og.appendChild(o); }
    sel.appendChild(og);
  }
  sel.addEventListener('change', () => {
    if (sel.value === '') return;
    const t = M.labels[+sel.value];
    if (state.mode === 'walk') {
      // stand a little south of the label and look towards it
      teleport(t.x, t.z + 1200, t.l, 0, -0.05);
      const dx = t.x * S - P.x, dz = t.z * S - P.z; P.yaw = Math.atan2(-dx, -dz);
    } else { orbit.t.set(t.x * S, LV[t.l].floor * S, t.z * S); orbit.r = 14; state.view = t.l; applyVisibility(); syncLevelButtons(); }
    sel.value = '';
    sel.blur();
  });

  // ------------------------------------------------------------------ boot
  function resize() {
    const w = innerWidth, h = innerHeight;
    renderer.setSize(w, h, false); camera.aspect = w / h; camera.updateProjectionMatrix();
  }
  addEventListener('resize', resize); resize();
  goLevel('G');
  setMode('walk');
  setTimeout(() => $('help').classList.add('fade'), 14000);

  function frame(now) {
    const dt = Math.min(0.05, (now - last) / 1000); last = now;
    update(dt); drawHUD(dt); drawMini();
    renderer.render(scene, camera);
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);

  // reachability test: flood-fill every spot a walker can reach (same collision + stair rules as walking)
  function reach() {
    const q = 0.1, W = Math.round((BOUNDS.x1 - BOUNDS.x0) / q), H = Math.round((BOUNDS.z1 - BOUNDS.z0) / q);
    const seen = new Map(); const sp = M.spawns.G; const fr = findFree(sp.x * S, sp.z * S, 0);
    const key = (ix, iz, f) => (Math.round(f * 20) * H + iz) * W + ix;
    const st = [[Math.round((fr[0] - BOUNDS.x0) / q), Math.round((fr[1] - BOUNDS.z0) / q), 0]];
    seen.set(key(st[0][0], st[0][1], 0), 1);
    const out = [];
    while (st.length) {
      const [ix, iz, f] = st.pop(); out.push([ix * q + BOUNDS.x0, iz * q + BOUNDS.z0, f]);
      for (const [dx, dz] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const nx = ix + dx, nz = iz + dz; if (nx < 0 || nz < 0 || nx >= W || nz >= H) continue;
        const x = nx * q + BOUNDS.x0, z = nz * q + BOUNDS.z0;
        if (blocked(x, z, f)) continue;
        const nf = surfaceAt(x, z, f); const k = key(nx, nz, nf);
        if (seen.has(k)) continue; seen.set(k, 1); st.push([nx, nz, nf]);
      }
    }
    const rooms = M.labels.map((t) => {
      const fl = LV[t.l].floor * S; let best = 1e9;
      for (const o of out) { if (Math.abs(o[2] - fl) > 0.45 && !(t.l === 'G' && o[2] < 0.3)) continue; const d = Math.hypot(o[0] - t.x * S, o[1] - t.z * S); if (d < best) best = d; }
      return [t.l + ' ' + t.t, +best.toFixed(2)];
    });
    return { cells: out.length, maxFeet: Math.max(...out.map((o) => o[2])), rooms };
  }

  // hooks for automated screenshots / debugging
  window.__tour = {
    teleport: (x, z, l, yaw, pitch) => teleport(x, z, l, yaw, pitch),
    setMode, setView: (v) => { state.view = v; applyVisibility(); syncLevelButtons(); },
    orbit: (o) => Object.assign(orbit, o, o.t ? { t: new THREE.Vector3(o.t[0], o.t[1], o.t[2]) } : {}),
    state, P, key: (k, v) => { keys[k] = v; }, setCeil: (v) => { state.ceil = v; applyVisibility(); syncUI(); },
    setLabels: (v) => { state.labels = v; applyVisibility(); syncUI(); }, setCut: (v) => { state.cut = v; applyVisibility(); syncUI(); },
    counts: { coll: COLL.length, surf: SURF.length, meshes: cutMeshes.length }, reach,
  };
})();
